<script lang="ts">
 import {onMount,untrack} from 'svelte';import {invoke} from '@tauri-apps/api/core';import {listen} from '@tauri-apps/api/event';import {getCurrentWebviewWindow} from '@tauri-apps/api/webviewWindow';import {open} from '@tauri-apps/plugin-dialog';import {t,type MessageKey} from '$lib/i18n';import type {FileInfo,ColumnInfo} from '$lib/columns';import FilePanel from '$lib/FilePanel.svelte';import Settings from '$lib/Settings.svelte';import {preferences,session,refresh} from '$lib/preferences.svelte';
 let tabs=$state<FileInfo[]>([]),active=$state(''),busy=$state(false),dragging=$state(false),showSettings=$state(false),error=$state<{message:string;detail:string}|null>(null);let file=$derived(tabs.find(f=>f.id===active)??null);let queue=Promise.resolve(),disposed=false;
 function showError(cause:unknown){const e=cause as {code?:string;detail?:string};const keys=['wrong_extension','not_found','access_denied','unreadable','not_a_file','task_failed','parse_failed','encrypted','resource_limit','invalid_request','file_changed','tab_limit'];error={message:t((keys.includes(e?.code??'')?e.code:'unknown') as MessageKey),detail:e?.detail??String(cause)};return error;}
 async function display(result:FileInfo){const columns:ColumnInfo[]=[];for(let offset=0;offset<result.column_count;offset+=500)columns.push(...await invoke<ColumnInfo[]>('display_columns',{id:result.id,offset,limit:500}));return {...result,columns};}
 function load(paths:string[]){queue=queue.then(async()=>{if(disposed)return;busy=true;error=null;const failures:string[]=[];for(const path of paths){try{const result=await invoke<FileInfo>('open_file',{path});const existing=tabs.find(t=>t.id===result.id);if(!existing){try{tabs=[...tabs,await display(result)];}catch(e){await invoke('close_file',{id:result.id}).catch(()=>{});throw e;}}active=result.id;}catch(e){const failure=showError(e);failures.push(path+': '+failure.message);}}if(failures.length)error={message:t('someFilesFailed'),detail:failures.join('\n')};await refresh();busy=false;}).catch(e=>{busy=false;showError(e);});return queue;}
 async function closeTab(id:string){busy=true;try{await invoke('close_file',{id});const index=tabs.findIndex(f=>f.id===id);tabs=tabs.filter(f=>f.id!==id);if(active===id)active=tabs[Math.max(0,index-1)]?.id??'';error=null;}catch(e){showError(e);}finally{busy=false;}}
 async function choose(){if(busy)return;try{const paths=await open({multiple:true,directory:false,filters:[{name:t('parquetFile'),extensions:['parquet']}]});if(paths)await load(Array.isArray(paths)?paths:[paths]);}catch(e){showError(e);}}
 function size(bytes:string){const n=Number(bytes);return n<1024?`${n} B`:n<1024**2?`${(n/1024).toFixed(2)} KiB`:n<1024**3?`${(n/1024**2).toFixed(2)} MiB`:`${(n/1024**3).toFixed(2)} GiB`;}
 function readablePath(path:string){return path.replace(/^\\\\\?\\UNC\\/,'\\\\').replace(/^\\\\\?\\/,'');}
 function keydown(event:KeyboardEvent){if(event.ctrlKey&&event.key.toLowerCase()==='o'){event.preventDefault();void choose();}}
 $effect(()=>{document.documentElement.dataset.theme=preferences.theme;});
 $effect(()=>{const time=preferences.time_mode;untrack(()=>{void(async()=>{for(const tab of [...tabs]){try{const updated=await display(tab);if(time===preferences.time_mode)tabs=tabs.map(f=>f.id===tab.id?updated:f);}catch{}}})();});});
 onMount(()=>{const off:(()=>void)[]=[];void(async()=>{try{
  await refresh();
  off.push(await listen<{owner:string;request:string}|null>('task_state',e=>{session.task=e.payload;if(!e.payload)session.progress='';}));session.task=await invoke('task_status');
  off.push(await listen<{request:string;progress:{done:number;total:number}}>('enum_progress',e=>{if(e.payload.request===session.task?.request)session.progress=`${e.payload.progress.done}/${e.payload.progress.total} RG`;}));
  off.push(await listen<{request:string;done:number;total:number}>('sample_progress',e=>{if(e.payload.request===session.task?.request)session.progress=`${e.payload.done}/${e.payload.total}`;}));
  off.push(await listen<{request:string;done:number;phase:string}>('dictionary_progress',e=>{if(e.payload.request===session.task?.request)session.progress=`${t(('dictionaryPhase_'+e.payload.phase) as MessageKey)} · ${e.payload.done}`;}));
  off.push(await listen('open_requests',()=>{void invoke<string[]>('startup_paths').then(load);}));
  off.push(await getCurrentWebviewWindow().onDragDropEvent(({payload})=>{dragging=payload.type==='enter'||payload.type==='over';if(payload.type==='drop')void load(payload.paths);}));
  const paths=await invoke<string[]>('startup_paths');if(paths.length)await load(paths);
 }catch(e){showError(e);}})();return()=>{disposed=true;off.forEach(f=>f());};});
</script>

<svelte:head><title>ParquetLens</title><meta name="description" content={t('subtitle')}/></svelte:head>
<svelte:window onkeydown={keydown}/><div class="app"><header><div class="brand"><span class="logo" aria-hidden="true">▥</span><div><strong>ParquetLens</strong><small>{t('subtitle')}</small></div></div><div class="header-actions"><button class="primary" onclick={choose} disabled={busy}>{t('open')} <kbd>Ctrl + O</kbd></button><select aria-label={t('recentFiles')} value="" onchange={e=>{if(e.currentTarget.value)void load([e.currentTarget.value]);e.currentTarget.value='';}}><option value="">{t('recentFiles')}</option>{#each preferences.recent as path}<option value={path}>{readablePath(path)}</option>{/each}</select><button onclick={()=>showSettings=true}>{t('settings')}</button></div></header>
<main>{#if session.warning}<p class="settings-warning">{t('settingsSessionOnly')} {session.warning}</p>{/if}{#if error}<section class="error" role="alert"><div><strong>{t('errorTitle')}</strong><p>{error.message}</p>{#if error.detail}<details><summary>{t('details')}</summary><pre>{error.detail}</pre></details>{/if}</div><button class="icon-button" aria-label={t('dismiss')} onclick={()=>error=null}>×</button></section>{/if}
{#if tabs.length}<nav class="tabs" aria-label={t('fileTabs')}>{#each tabs as tab(tab.id)}<div class="tab" class:active={active===tab.id}><button title={readablePath(tab.path)} onclick={()=>active=tab.id}>{tab.name}</button><button aria-label={`${t('closeTab')} ${tab.name}`} disabled={busy} onclick={()=>closeTab(tab.id)}>×</button></div>{/each}</nav>{/if}
{#if file}<section class="file-card"><div class="card-heading"><span class="badge">PARQUET</span><button class="secondary" disabled={busy} onclick={()=>file&&closeTab(file.id)}>{t('close')}</button></div><h1>{file.name}</h1><p class="success">● {t('stage')}</p><dl><div><dt>{t('filename')}</dt><dd>{file.name}</dd></div><div><dt>{t('filesize')}</dt><dd class="numeric">{size(file.size_bytes)} <span class="muted">({BigInt(file.size_bytes).toLocaleString('zh-CN')} {t('bytes')})</span></dd></div><div><dt>{t('filepath')}</dt><dd class="path">{readablePath(file.path)}</dd></div></dl></section>
{#each tabs as tab(tab.id)}<div class="file-panel" hidden={active!==tab.id}><FilePanel file={tab}/></div>{/each}
{:else}<section class="empty"><button class="dropzone" onclick={choose} disabled={busy}><span class="file-icon" aria-hidden="true">▥</span><h1>{dragging?t('drop'):t('title')}</h1><p>{busy?t('opening'):t('intro')}</p><span class="extension">.parquet</span></button><div class="features">{#each ['featureColumns','featureEnums','featureExport'] as feature}<div><span>{t(feature as MessageKey)}</span><small>{t('available')}</small></div>{/each}</div></section>{/if}</main>
<footer><span><i class:working={busy}></i>{busy?t('opening'):file?t('selected'):t('ready')}</span><span>{t('local')} · {t('step')}</span></footer>{#if dragging}<div class="drop-overlay"><strong>{t('drop')}</strong></div>{/if}
{#if session.task}<div class="global-task" role="status"><span>{t('backgroundTask')}: {tabs.find(f=>f.id===session.task?.owner)?.name??''} · {session.progress}</span><button onclick={()=>{const task=session.task;if(task)void invoke('cancel_task',{id:task.owner,request:task.request});}}>{t('cancelTask')}</button></div>{/if}
{#if showSettings}<Settings onclose={()=>showSettings=false}/>{/if}</div>
<style>
  
  :global(*){box-sizing:border-box} :global(body){margin:0;font-family:"Segoe UI","Microsoft YaHei",sans-serif;color:var(--text);background:var(--bg);font-size:14px}
  :global(:root){color-scheme:light;--bg:#f5f7fa;--surface:#fff;--text:#202e41;--muted:#748096;--line:#e2e7ef;--accent:#3268cf;--soft:#edf3ff;--success:#248269}
  :global(button){font:inherit;cursor:pointer} :global(button:disabled){cursor:wait;opacity:.55} :global(button:focus-visible),:global(summary:focus-visible){outline:3px solid #7ca5ef;outline-offset:4px}
  .app{min-height:100vh;display:flex;flex-direction:column}header{height:76px;padding:0 36px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);background:var(--surface);gap:16px}
  .brand{display:flex;align-items:center;gap:13px}.logo{background:var(--accent);color:white;border-radius:11px;width:42px;height:42px;display:grid;place-items:center;font-size:30px}.brand strong{font-size:20px;letter-spacing:-.5px}.brand small{display:block;color:var(--muted);font-size:11px;margin-top:4px}
  .primary{border:0;background:var(--accent);color:white;padding:11px 16px;border-radius:7px}.primary kbd{margin-left:14px;font:11px "Segoe UI",sans-serif;opacity:.7}
  main{flex:1;padding:20px 24px;display:flex;flex-direction:column}.empty{flex:1;display:flex;flex-direction:column;justify-content:center;max-width:820px;width:100%;margin:0 auto}.dropzone{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:310px;width:100%;padding:35px;background:var(--surface);border:1.5px dashed #bdcadd;border-radius:14px;color:var(--text)}.dropzone:hover{border-color:var(--accent);background:var(--soft)}.file-icon{font-size:53px;color:var(--accent);background:var(--soft);width:82px;height:88px;border-radius:16px;display:grid;place-items:center}h1{font-size:25px;font-weight:600;margin:14px 0 8px;overflow-wrap:anywhere}.dropzone p{color:var(--muted);margin:4px 0 22px}.extension{font-family:Consolas,monospace;font-size:12px;color:var(--muted);border:1px solid var(--line);padding:4px 10px;border-radius:5px}
  .features{display:flex;justify-content:space-around;gap:18px;margin-top:26px}.features div{display:flex;flex-direction:column;text-align:center;gap:6px;color:var(--muted);font-size:13px}.features small{font-size:10px;opacity:.75}
  footer{display:flex;justify-content:space-between;gap:20px;padding:13px 26px;border-top:1px solid var(--line);color:var(--muted);font-size:11px;background:var(--surface)}footer span{display:flex;align-items:center;gap:8px}i{width:6px;height:6px;border-radius:50%;background:var(--success)}i.working{background:#c18a2a}
  .file-card{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:16px 20px;width:100%;margin:0}.card-heading{display:flex;align-items:center;justify-content:space-between}.badge{color:var(--accent);background:var(--soft);font-size:11px;letter-spacing:1px;padding:6px 10px;border-radius:4px}.secondary{background:transparent;border:1px solid var(--line);border-radius:6px;padding:7px 12px;color:var(--muted)}.success{color:var(--success);font-size:12px;margin-bottom:12px}dl{margin:0}dl>div{display:grid;grid-template-columns:110px minmax(0,1fr);border-top:1px solid var(--line);padding:9px 0;gap:16px}dt{color:var(--muted)}dd{margin:0;user-select:text;overflow-wrap:anywhere}.numeric,.path{font-family:Consolas,"Microsoft YaHei",monospace}.muted{color:var(--muted);font-size:12px}
  .error{display:flex;justify-content:space-between;background:#fff1ee;border:1px solid #f0c9bd;color:#9c3b28;border-radius:8px;padding:16px 20px;margin-bottom:18px;gap:16px}.error>div{min-width:0}.error p{margin:7px 0}.error pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.error summary{cursor:pointer;font-size:12px}.icon-button{align-self:flex-start;background:transparent;border:0;font-size:22px;color:inherit}.drop-overlay{position:fixed;inset:10px;background:color-mix(in srgb,var(--soft) 93%,transparent);border:2px dashed var(--accent);border-radius:12px;display:grid;place-items:center;pointer-events:none;color:var(--accent);font-size:26px}
  @media(prefers-color-scheme:dark){:global(:root:not([data-theme="light"])){color-scheme:dark;--bg:#151b25;--surface:#1c2532;--text:#e2e9f2;--muted:#99a7bc;--line:#303c4e;--accent:#73a2ff;--soft:#24344e;--success:#73c5a6}.primary{background:#386bcb;color:#fff}.dropzone{border-color:#40536f}.error{background:#382822;border-color:#684435;color:#ffb49c}}
  @media(max-width:740px){header{padding:0 22px}main{padding:22px}footer{padding:12px 18px}.primary kbd{display:none}h1{font-size:22px}}
:global(:root[data-theme="dark"]){color-scheme:dark;--bg:#151b25;--surface:#1c2532;--text:#e2e9f2;--muted:#99a7bc;--line:#303c4e;--accent:#73a2ff;--soft:#24344e;--success:#73c5a6}.header-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.header-actions button,.header-actions select{font:inherit;font-size:12px;padding:8px;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:6px;max-width:200px}.tabs{display:flex;gap:6px;margin-bottom:16px;overflow:auto}.tab{display:flex;flex-shrink:0;border:1px solid var(--line);background:var(--surface);border-radius:6px}.tab.active{border-color:var(--accent);background:var(--soft)}.tab button{border:0;background:transparent;color:var(--text);padding:9px;font-size:12px;max-width:220px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.global-task{position:fixed;bottom:0;left:0;right:0;z-index:40;background:var(--surface);border-top:1px solid var(--line);padding:12px 22px;display:flex;gap:14px;align-items:center;font-size:12px}.global-task button{border:1px solid var(--line);background:var(--bg);color:var(--text);padding:6px;border-radius:5px}.settings-warning{font-size:12px;color:var(--muted)}:global([hidden]){display:none!important}</style>


